      SUBROUTINE RINV2CC     CALCULATES INVERSE OF SECOND-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'RS.CIN'      INCLUDE 'TR.CIN'      INCLUDE 'TS.CIN'C      DO 30 J = 1, 5      DO 10 L1 = 1, 6      DO 10 L2 = 1, 6      TR(J,L1,L2) = 0.0   10 CONTINUE      IND = 0      DO 20 L2 = 1, 6      DO 20 L1 = 1, L2      IND = IND + 1      DO 20 K = 1, 6      TR(J,K,L2) = TR(J,K,L2) + TS(J,IND)*RS(L1,K)   20 CONTINUE   30 CONTINUEC      DO 60 J = 1, 5      DO 40 IND = 1, 21      TT(J,IND) = 0.0   40 CONTINUE      DO 50 K = 1, 6      DO 50 L1 = 1, 6      DO 50 L2 = 1, 6      IND = INDEX2(L1,L2)      TT(J,IND) = TT(J,IND) + TR(J,L1,K)*RS(K,L2)   50 CONTINUE   60 CONTINUEC      DO 80 J = 1, 5      DO 80 IND = 1, 21      SS = 0.0      DO 70 K = 1, 5      SS = SS + RS(J,K)*TT(K,IND)   70 CONTINUE      TS(J,IND) = - SS   80 CONTINUEC      RETURN      END